<template><div class="app-container ps-page"><h2>知识问答</h2><el-alert v-if="error||stream.error.value" :title="error||stream.error.value" type="error" :closable="false" class="ps-error"/><div class="chat-layout"><ConversationList :selected="current?.id" :refresh-key="refreshKey" @select="selectConversation" @create="startNew"/><section class="chat-main ps-panel"><div class="ps-toolbar"><strong>{{current?.title||'选择或新建会话'}}</strong><el-button v-if="current" v-hasPermi="['paismart:conversation:list']" link :disabled="creating||loading||!scopeLoaded||generating" @click="archive">归档会话</el-button><el-button v-if="stream.state.value==='disconnected'||stream.state.value==='failed'" :disabled="!stream.generationId.value||creating||loading||!scopeLoaded" @click="resumeCurrent">恢复生成</el-button></div><div class="scope-toolbar"><template v-if="current"><span role="status">当前会话检索范围：{{currentScopeLabel}}</span><small class="ps-muted">创建后固定；更换范围请新建会话。</small></template><template v-else><label for="new-conversation-space">新会话检索范围</label><el-select id="new-conversation-space" v-model="newSpaceId" :loading="spaceLoading" :disabled="creating" aria-label="新会话检索范围"><el-option label="全部有权空间" value=""/><el-option v-for="space in visibleSpaces" :key="space.id" :label="space.name" :value="String(space.id)"/></el-select></template><el-button v-if="spaceError" link @click="loadSpaces">重新读取空间</el-button></div><el-alert v-if="spaceError" :title="spaceError" type="warning" :closable="false"/><div class="message-list" aria-live="polite" v-loading="loading"><ChatMessage v-for="message in messages" :key="message.id" :message="message" @reference="openReference"/><ChatMessage v-if="showStream" :message="streamMessage" streaming @reference="openReference"/><el-empty v-if="!messages.length&&!showStream" description="提问后将从有权访问的知识中检索回答"/></div><el-pagination v-if="messageTotal>messageSize" v-model:current-page="messagePage" :page-size="messageSize" :total="messageTotal" layout="total,prev,pager,next" :disabled="generating||loading" @current-change="readMessages(false)"/><p v-if="stream.tools.value.length" class="ps-muted">工具执行：<span v-for="tool in stream.tools.value" :key="tool.name">{{tool.name}}（{{tool.state==='COMPLETE'?'已完成':tool.state==='RUNNING'?'执行中':tool.state}}） </span></p><el-input v-model="draft" type="textarea" :rows="4" maxlength="16000" show-word-limit placeholder="输入问题，Ctrl+Enter 发送" :disabled="generating" @keydown.ctrl.enter.prevent="send" aria-label="问答问题"/><div class="ps-toolbar" style="margin-top:12px"><el-button v-hasPermi="['paismart:chat:send']" type="primary" :disabled="!draft.trim()||generating||creating||!!current&&!scopeLoaded" :loading="stream.state.value==='connecting'" @click="send">发送问题</el-button><el-button v-if="generating" :disabled="!stream.generationId.value||stream.state.value==='stopping'" @click="stream.stop()">停止生成</el-button><span role="status">{{streamStatus}}</span></div></section><aside class="ps-panel reference-list"><h3>当前回答引用</h3><el-empty v-if="!currentReferences.length" description="回答引用将在这里显示" :image-size="60"/><el-button v-for="(reference,i) in currentReferences" :key="reference.id" class="reference-button" text @click="openReference(reference)">[{{i+1}}] {{reference.title}}<br/>{{reference.page?'第 '+reference.page+' 页':''}} <span class="citation-state" :class="{'citation-state--suspicious':referenceVerdict(reference).suspicious}">{{referenceVerdict(reference).label}}</span><small v-if="referenceVerdict(reference).suspicious" class="citation-reason">{{referenceVerdict(reference).reason}}</small></el-button><p class="ps-muted">引用按生成时的内容版本读取，权限变更后由服务端重新判定。</p></aside></div><el-dialog v-model="createOpen" title="新建会话" width="480px"><el-form label-width="110px"><el-form-item label="检索范围"><el-select v-model="newSpaceId" :loading="spaceLoading" :disabled="creating" aria-label="新会话检索范围"><el-option label="全部有权空间" value=""/><el-option v-for="space in visibleSpaces" :key="space.id" :label="space.name" :value="String(space.id)"/></el-select></el-form-item></el-form><p class="ps-muted">全部有权空间会按提问时的权限检索；指定空间仅检索该空间。会话创建后范围固定。</p><el-alert v-if="spaceError" :title="spaceError" type="warning" :closable="false"/><el-alert v-if="createError" :title="createError" type="error" :closable="false"/><template #footer><el-button :disabled="creating" @click="createOpen=false">取消</el-button><el-button type="primary" :loading="creating" @click="create">创建会话</el-button></template></el-dialog><ReferencePreview v-model="referenceOpen" :reference="selectedReference"/></div></template>
<script setup lang="ts">
import { computed, onMounted, ref, shallowRef } from 'vue'
import { useRoute } from 'vue-router'
import { conversationAction, conversationMessages, createConversation } from '@/api/paismart/conversations'
import { myMembership } from '@/api/paismart/spaces'
import { getActiveGeneration } from '@/api/paismart/chat'
import type { Conversation, Id, Message, Reference } from '@/types/paismart'
import { errorText } from '../composables/usePage'
import {referenceVerdict} from '../composables/referencePresentation'
import { useChatStream } from '../composables/useChatStream'
import ConversationList from './components/ConversationList.vue'
import ChatMessage from './components/ChatMessage.vue'
import ReferencePreview from './components/ReferencePreview.vue'
import '../common.css'
const route=useRoute(),current=shallowRef<Conversation>(),messages=shallowRef<Message[]>([]),draft=ref(''),error=ref(''),loading=ref(false),refreshKey=ref(0),showStream=ref(false),referenceOpen=ref(false),selectedReference=shallowRef<Reference>()
const currentReferences=computed(()=>showStream.value?stream.references.value:([...messages.value].reverse().find(message=>message.role==='assistant')?.references??[]))
const messagePage=ref(1),messageTotal=ref(0),messageSize=100
const visibleSpaces=shallowRef<{id:Id;name:string}[]>([]),newSpaceId=ref(''),spaceLoading=ref(false),spaceError=ref(''),scopeLoaded=ref(false),createOpen=ref(false),creating=ref(false),createError=ref('')
const currentScopeLabel=computed(()=>{if(!scopeLoaded.value)return '未读取';if(!current.value?.spaceId)return '全部有权空间';if(spaceLoading.value)return '正在核对可见空间';if(spaceError.value)return '指定空间（可见权限未读取）';return visibleSpaces.value.find(space=>String(space.id)===String(current.value?.spaceId))?.name??'原会话空间已不可访问'})
let serial=0,selectionSerial=0,spaceSerial=0
const recoveryTargets=new Map<string,Id>()
async function loadSpaces(){const version=++spaceSerial;spaceLoading.value=true;spaceError.value='';visibleSpaces.value=[];try{const member=(await myMembership()).data;if(version!==spaceSerial)return;if(member.eligible===false)throw new Error('当前知识库资格未启用，空间与问答权限仍由服务端核对');if(!Array.isArray(member.visibleSpaces))throw new Error('当前服务未提供可见空间名称，可继续使用全部有权空间；请更新服务后重试');visibleSpaces.value=member.visibleSpaces}catch(e){if(version===spaceSerial)spaceError.value=errorText(e)}finally{if(version===spaceSerial)spaceLoading.value=false}}
function startNew(){if(generating.value||creating.value){error.value='请先停止当前生成，再新建会话';return}newSpaceId.value='';createError.value='';createOpen.value=true;void loadSpaces()}
const stream=useChatStream(()=>{void finished()}),generating=computed(()=>['connecting','generating','stopping'].includes(stream.state.value)),streamMessage=computed<Message>(()=>({id:'stream',role:'assistant',content:stream.text.value,references:stream.references.value,state:streamStatus.value})),streamStatus=computed(()=>({idle:'',connecting:'正在连接',generating:'正在生成',stopping:'正在停止',done:'生成完成',stopped:'已停止',disconnected:'连接中断',failed:'生成未完成'} as Record<string,string>)[stream.state.value])
async function readMessages(tail=true){if(!current.value)return;const id=current.value.id,version=++serial;loading.value=true;error.value='';try{let response=await conversationMessages(id,{pageNum:tail?1:messagePage.value,pageSize:messageSize});if(tail){const last=Math.max(1,Math.ceil(response.total/messageSize));if(last>1)response=await conversationMessages(id,{pageNum:last,pageSize:messageSize});if(version===serial)messagePage.value=last}if(version===serial){messages.value=response.rows;messageTotal.value=response.total}}catch(e){if(version===serial)error.value=errorText(e)}finally{if(version===serial)loading.value=false}}
function rememberRecovery(){if(!current.value||String(stream.conversationId.value)!==String(current.value.id))return;const key=String(current.value.id);if(stream.generationId.value&&['disconnected','failed'].includes(stream.state.value))recoveryTargets.set(key,stream.generationId.value);else recoveryTargets.delete(key)}
function resetConversationStream(id?:Id){rememberRecovery();stream.reset(id);const target=id===undefined?undefined:recoveryTargets.get(String(id));if(target){stream.generationId.value=target;stream.state.value='disconnected'}}
async function selectConversation(row:Conversation){if(generating.value||creating.value){error.value='请先停止当前生成，再切换会话';return}const selection=++selectionSerial;++serial;if(current.value?.id!==row.id)resetConversationStream(row.id);scopeLoaded.value=false;current.value=row;messages.value=[];stream.references.value=[];stream.tools.value=[];showStream.value=false;error.value='';loading.value=true;try{const response=await conversationAction(row,'switch');if(selection!==selectionSerial)return;current.value=response.data;scopeLoaded.value=true;await Promise.all([readMessages(),loadSpaces()])}catch(e){if(selection===selectionSerial)error.value=errorText(e)}finally{if(selection===selectionSerial)loading.value=false}}
async function create(){if(generating.value||creating.value)return;error.value='';createError.value='';if(newSpaceId.value&&!visibleSpaces.value.some(space=>String(space.id)===newSpaceId.value)){createError.value='所选空间已不可见，请重新读取空间后选择';error.value=createError.value;return}creating.value=true;try{const row=(await createConversation('新会话',newSpaceId.value||undefined)).data;++selectionSerial;++serial;resetConversationStream(row.id);current.value=row;scopeLoaded.value=true;messages.value=[];stream.references.value=[];stream.tools.value=[];showStream.value=false;messageTotal.value=0;messagePage.value=1;createOpen.value=false;refreshKey.value++}catch(e){createError.value=errorText(e);error.value=createError.value}finally{creating.value=false}}
async function send(){if(!draft.value.trim()||generating.value||creating.value)return;error.value='';if(!current.value)await create();if(!current.value||!scopeLoaded.value)return;recoveryTargets.delete(String(current.value.id));const question=draft.value.trim();messages.value=[...messages.value,{id:crypto.randomUUID(),role:'user',content:question}];showStream.value=true;await stream.send(current.value.id,question);if(stream.state.value!=='failed')draft.value=''}
async function finished(){refreshKey.value++;if(!current.value||stream.conversationId.value&&String(stream.conversationId.value)!==String(current.value.id))return;const selection=selectionSerial,id=current.value.id;if(['done','stopped'].includes(stream.state.value))recoveryTargets.delete(String(id));await readMessages();if(selection===selectionSerial&&current.value?.id===id&&!error.value)showStream.value=false}
async function resumeCurrent(){if(!current.value||creating.value||loading.value||!scopeLoaded.value||String(stream.conversationId.value)!==String(current.value.id))return;showStream.value=true;await stream.resume()}
async function archive(){if(!current.value||generating.value||creating.value||loading.value||!scopeLoaded.value)return;const row=current.value,selection=selectionSerial;try{await conversationAction(row,'archive');refreshKey.value++;if(selection!==selectionSerial||current.value?.id!==row.id)return;++selectionSerial;++serial;recoveryTargets.delete(String(row.id));stream.reset();current.value=undefined;scopeLoaded.value=false;messages.value=[];showStream.value=false}catch(e){if(selection===selectionSerial&&current.value?.id===row.id)error.value=errorText(e)}}
function openReference(reference:Reference){selectedReference.value=reference;referenceOpen.value=true}
onMounted(async()=>{void loadSpaces();let selection=selectionSerial;try{const active=(await getActiveGeneration()).data;if(selection!==selectionSerial)return;if(active){selection=selectionSerial+1;await selectConversation({id:active.conversationId,title:'恢复中的会话',rowVersion:0,archived:false});if(selection!==selectionSerial||current.value?.id!==active.conversationId||!scopeLoaded.value)return;showStream.value=true;await stream.resume(active.generationId)}else if(typeof route.query.conversationId==='string'){selection=selectionSerial+1;await selectConversation({id:route.query.conversationId,title:'历史会话',rowVersion:0,archived:false})}}catch(e){if(selection===selectionSerial)error.value=errorText(e)}})
</script>
<style scoped>.scope-toolbar{display:flex;flex-wrap:wrap;align-items:center;gap:12px;margin:0 0 16px}.scope-toolbar .el-select{width:240px}.chat-layout{display:grid;grid-template-columns:250px minmax(320px,1fr) 250px;gap:16px}.chat-main{min-width:0}.message-list{min-height:300px;max-height:60vh;overflow:auto}.reference-button{width:100%;height:auto;justify-content:flex-start;text-align:left;margin:0 0 12px;white-space:normal}.reference-button :deep(>span){display:block;width:100%;overflow-wrap:anywhere}@media(max-width:1250px){.chat-layout{grid-template-columns:230px minmax(0,1fr)}.reference-list{grid-column:1/-1}}@media(max-width:760px){.chat-layout{grid-template-columns:1fr}}</style>
